import os
import re
import uuid
from datetime import datetime, timezone

_ALLOWED_CONTENT_TYPES = frozenset({"image/jpeg", "image/png"})
_MAX_BYTES = 5 * 1024 * 1024
_SAFE_CHAR_RE = re.compile(r"[^A-Za-z0-9._-]")


def init_db(conn):
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            s3_key TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
        """
    )
    conn.commit()


def save_photo_metadata(conn, title, description, s3_key):
    uploaded_at = datetime.now(timezone.utc).isoformat()
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO photos (title, description, s3_key, uploaded_at) VALUES (?, ?, ?, ?)",
        (title, description, s3_key, uploaded_at),
    )
    new_id = cur.lastrowid
    conn.commit()
    return int(new_id)


def _escape_like(text):
    return text.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def search_photos(conn, term):
    if not isinstance(term, str):
        raise TypeError("term must be a str")
    pattern = "%" + _escape_like(term.lower()) + "%"
    cur = conn.cursor()
    cur.execute(
        """
        SELECT id, title, description, s3_key, uploaded_at
        FROM photos
        WHERE LOWER(title) LIKE ? ESCAPE '\\'
           OR LOWER(description) LIKE ? ESCAPE '\\'
        ORDER BY id ASC
        """,
        (pattern, pattern),
    )
    rows = cur.fetchall()
    return [
        {
            "id": row[0],
            "title": row[1],
            "description": row[2],
            "s3_key": row[3],
            "uploaded_at": row[4],
        }
        for row in rows
    ]


def _safe_name(filename):
    if not isinstance(filename, str):
        raise ValueError("filename must be a str")
    base = re.split(r"[\\/]", filename)[-1]
    safe = _SAFE_CHAR_RE.sub("_", base)
    if safe in ("", ".", ".."):
        raise ValueError("filename does not produce a usable name")
    return safe


def upload_photo(s3, bucket, filename, data, content_type):
    if content_type not in _ALLOWED_CONTENT_TYPES:
        raise ValueError("unsupported content type")
    if data is None or len(data) > _MAX_BYTES:
        raise ValueError("data must be present and at most 5 MiB")
    safe = _safe_name(filename)
    key = "photos/" + uuid.uuid4().hex + "/" + safe
    s3.put_object(Bucket=bucket, Key=key, Body=data, ContentType=content_type)
    return key


def photo_url(s3, bucket, key, expires=3600):
    if (
        isinstance(expires, bool)
        or not isinstance(expires, int)
        or not 1 <= expires <= 3600
    ):
        raise ValueError("expires must be an integer between 1 and 3600")
    return s3.generate_presigned_url(
        "get_object",
        Params={"Bucket": bucket, "Key": key},
        ExpiresIn=expires,
    )


def handle_upload(conn, s3, bucket, title, description, filename, data, content_type):
    key = upload_photo(s3, bucket, filename, data, content_type)
    try:
        return save_photo_metadata(conn, title, description, key)
    except Exception:
        try:
            s3.delete_object(Bucket=bucket, Key=key)
        except Exception:
            pass
        raise
